"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53516"],{74454(e){e.exports=JSON.parse('{"id":"FIN-294","slug":"scarcity","term":"Scarcity","also_known_as":[],"difficulty":"Beginner","definition":"Scarcity is the basic economic problem that resources are limited while human wants are virtually unlimited, so people and societies must make choices.","explanation":["There is never enough time, money, land, labour or materials to produce everything everyone wants. This is true for individuals, businesses and whole countries. Scarcity means every choice involves giving something up.","For an individual, scarcity might mean choosing between spending money on a holiday or saving it for a house. For a business, it might mean choosing between hiring more staff or buying new equipment. For a government, it might mean choosing between spending more on healthcare or on education.","Because of scarcity, every choice has an opportunity cost: the value of the next best alternative that is given up.","Scarcity is also why prices exist. When something is scarce relative to demand, its price tends to rise, which encourages people to use less of it and producers to supply more. Scarcity is not the same as poverty. Even very wealthy people and countries face scarcity, because their resources are still finite and they still have to choose."],"note":"","total":1500,"prev":{"slug":"scalability","term":"Scalability"},"next":{"slug":"scenario-analysis","term":"Scenario Analysis"}}')}}]);